using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The class is instantiated per-call; constructor dependencies are injected from DI.
/// </summary>
[McpServerToolType]
public sealed class WeatherTools
{
    private readonly HttpClient _http;

    // HttpClient is injected via DI (registered through IHttpClientFactory)
    public WeatherTools(HttpClient httpClient)
    {
        _http = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city")]
    public async Task<string> GetCurrentWeather(
        [Description("City name, e.g. 'Seattle'")] string city,
        CancellationToken cancellationToken = default)
    {
        var response = await _http.GetAsync(
            $"/v1/current.json?q={Uri.EscapeDataString(city)}",
            cancellationToken);

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool, Description("Get weather forecast for a city")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of forecast days (1-3)")] int days = 3,
        CancellationToken cancellationToken = default)
    {
        var response = await _http.GetAsync(
            $"/v1/forecast.json?q={Uri.EscapeDataString(city)}&days={days}",
            cancellationToken);

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }
}

using McpServer.Tools;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();   // discovers all [McpServerToolType] classes

// Register a named HttpClient so DI can inject it into WeatherTools
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.BaseAddress = new Uri("https://api.weatherapi.com");
    client.DefaultRequestHeaders.Add("Accept", "application/json");
});

var app = builder.Build();
await app.RunAsync();

